SELECT IFNULL(SUM(feedback_quantity), 0)     AS feedbackQuantity,
       IFNULL(SUM(qualified_quantity), 0)    AS qualifiedQuantity,
       IFNULL(SUM(unqualified_quantity), 0)  AS unqualifiedQuantity
FROM mes_pro_feedback
WHERE deleted = 0
  AND status = ${@cn.iocoder.txgy.module.mes.enums.pro.MesProFeedbackStatusEnum@FINISHED.status}
  AND feedback_time >= #{beginTime}

      AND feedback_time < #{endTime}

SELECT level, COUNT(*) AS count
FROM mes_pro_andon_record
WHERE deleted = 0
  AND create_time >= #{beginTime}
  AND create_time < #{endTime}
GROUP BY level

SELECT IFNULL(reason, '其他') AS reason, COUNT(*) AS count
FROM mes_pro_andon_record
WHERE deleted = 0
  AND create_time >= #{beginTime}
  AND create_time < #{endTime}
GROUP BY reason
ORDER BY count DESC
LIMIT #{limit}

SELECT status, COUNT(*) AS count
FROM mes_dv_repair
WHERE deleted = 0
  AND require_date >= #{beginTime}
  AND require_date < #{endTime}
GROUP BY status

SELECT COUNT(*) AS totalCount,
       IFNULL(SUM(CASE WHEN request_date IS NULL OR finish_date <= request_date THEN 1 ELSE 0 END), 0) AS onTimeCount,
       IFNULL(SUM(CASE WHEN request_date IS NOT NULL AND finish_date > request_date THEN 1 ELSE 0 END), 0) AS overdueCount,
       IFNULL(AVG(CASE WHEN request_date IS NOT NULL AND finish_date > request_date
                            THEN DATEDIFF(finish_date, request_date) END), 0) AS avgOverdueDays
FROM mes_pro_work_order
WHERE deleted = 0
  AND status = ${@cn.iocoder.txgy.module.mes.enums.pro.MesProWorkOrderStatusEnum@FINISHED.status}
  AND finish_date >= #{beginTime}
  AND finish_date < #{endTime}

SELECT name, IFNULL(SUM(quantity), 0) AS quantity
FROM mes_qc_defect_record
WHERE deleted = 0
  AND create_time >= #{beginTime}
  AND create_time < #{endTime}
GROUP BY name
ORDER BY quantity DESC
LIMIT #{limit}

SELECT COUNT(*) AS totalCount,
       IFNULL(SUM(CASE WHEN status = ${@cn.iocoder.txgy.module.mes.enums.dv.MesDvCheckRecordStatusEnum@FINISHED.status} THEN 1 ELSE 0 END), 0) AS finishedCount
FROM mes_dv_check_record
WHERE deleted = 0
  AND check_time >= #{beginTime}
  AND check_time < #{endTime}

SELECT COUNT(*) AS totalCount,
       IFNULL(SUM(CASE WHEN status = ${@cn.iocoder.txgy.module.mes.enums.dv.MesDvMaintenRecordStatusEnum@SUBMITTED.status} THEN 1 ELSE 0 END), 0) AS submittedCount
FROM mes_dv_mainten_record
WHERE deleted = 0
  AND mainten_time >= #{beginTime}
  AND mainten_time < #{endTime}

SELECT DATE_FORMAT(feedback_time, '%Y-%m-%d') AS date, IFNULL(SUM(feedback_quantity), 0) AS quantity, IFNULL(SUM(qualified_quantity), 0) AS qualifiedQuantity, IFNULL(SUM(unqualified_quantity), 0) AS unqualifiedQuantity FROM mes_pro_feedback WHERE deleted = 0 AND status = ${@cn.iocoder.txgy.module.mes.enums.pro.MesProFeedbackStatusEnum@FINISHED.status} AND feedback_time >= #{beginTime}
AND feedback_time < #{endTime}
GROUP BY DATE_FORMAT(feedback_time, '%Y-%m-%d') ORDER BY date
